<section class="card form-card"><div class="section-heading compact"><div><h2>Akun dan kontak</h2><p>Username digunakan untuk masuk dan terpisah dari alamat email. Isi kata sandi saat ini untuk menyimpan perubahan.</p></div></div>
<form method="post" action="<?= site_url('profil/akun') ?>"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?>
<div class="form-grid"><label>Username<input name="username" minlength="4" maxlength="90" pattern="[a-z0-9._-]{4,90}" required value="<?= e($current_user->username ?: '') ?>" autocomplete="username"></label><label>Email<input type="email" name="email" value="<?= e($current_user->email) ?>" autocomplete="email" placeholder="Opsional"></label><label>Nomor telepon / WhatsApp<input type="tel" name="phone" pattern="08[0-9]{8,12}" value="<?= e($current_user->phone) ?>" placeholder="08..." inputmode="tel"></label><label>Kata sandi saat ini<input type="password" name="current_password" required autocomplete="current-password"></label></div>
<div class="form-actions"><button class="button primary" type="submit">Simpan akun</button><a class="button outline" href="<?= site_url('ganti-kata-sandi') ?>">Ganti kata sandi</a></div></form></section>
